<script lang="ts">
import {Component} from 'vue-property-decorator'
import PortalPageBase from '@/view/PortalPageBase'
import {breadcrumbList, canonicalUrl, pageMetaInfo, personReference, socialCardPath, stripHtml} from '@/model/Seo'
import {brandName} from '@/model/Brand'
import {CVContactIds} from '@/model/Data/CVData'
import {Locale} from '@/model/content/Locale'

@Component
export default class CV extends PortalPageBase {
  pageTitle = this.titles.cvPage
  summaryId = 'cv-summary-title'

  get printPath() {
    return Locale.activePathFor(this.constants.cvPrintPath)
  }

  get contacts() {
    return this.model.cv.printContacts.filter(contact => contact.id !== CVContactIds.website)
  }

  metaInfo(): any {
    const structuredData = {
      '@context': 'https://schema.org',
      '@graph': [
        {
          '@type': 'ProfilePage',
          name: this.titles.cvPage,
          description: this.titles.cvDescription,
          url: canonicalUrl(this.constants.cvPath),
          mainEntity: {
            ...personReference(),
            '@type': 'Person',
            name: stripHtml(this.model.profile.name),
            jobTitle: stripHtml(this.model.profile.title),
            email: 'mailto:dohan.rene@gmail.com'
          }
        },
        breadcrumbList([
          {name: brandName, path: '/'},
          {name: this.titles.homePage, path: this.constants.introductionPath},
          {name: this.titles.cvPage, path: this.constants.cvPath}
        ])
      ]
    }
    return pageMetaInfo(
      this.titles.cvSeoTitle,
      this.titles.cvDescription,
      this.constants.cvPath,
      socialCardPath(this.constants.cvPath),
      structuredData
    )
  }

  beforeRouteEnter(to: any, from: any, next: any) {
    super.beforeRouteEnter(to, from, next)
  }
}
</script>
